def _regular_group(labels):
    groups=collections.defaultdict(list)
    for i,v in enumerate(labels): groups[v].append(i)
    cand=[]
    for v,pos in groups.items():
        if len(pos)>=2:
            diffs=[b-a for a,b in zip(pos,pos[1:])]
            med=statistics.median(diffs)
            if med>1:
                cand.append((med,len(pos),v,pos))
    if not cand: return None
    # Repeated grid lines have gaps larger than the densely occurring fill rows/columns.
    return max(cand,key=lambda z:(z[0],z[1]))

def transform_candidate(grid):
    h,w=len(grid),len(grid[0])
    row_doms=[collections.Counter(row).most_common(1)[0][0] for row in grid]
    rg=_regular_group(row_doms)
    if rg is None: raise ValueError(('no row lattice',row_doms))
    hline_color, rows=rg[2],rg[3]
    col_doms=[collections.Counter(grid[r][c] for r in range(h)).most_common(1)[0][0] for c in range(w)]
    cg=_regular_group(col_doms)
    if cg is not None:
        cols=cg[3]
    else:
        # Grid columns can be hidden by the interior color in the column majority;
        # on horizontal separator rows, their intersections stand out from the line color.
        cols=[c for c in range(w) if sum(grid[r][c]!=hline_color for r in rows)>=2]
        # If only sparse marks are present, recover the regular lattice by the gap.
        # (In this task family the separator intersections are the repeated outliers.)
    if len(rows)<2 or len(cols)<2: raise ValueError((rows,cols,hline_color))
    fill=collections.Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[]
    for ri in range(len(rows)-1):
        line=[]
        for ci in range(len(cols)-1):
            corners=(grid[rows[ri]][cols[ci]],grid[rows[ri]][cols[ci+1]],grid[rows[ri+1]][cols[ci]],grid[rows[ri+1]][cols[ci+1]])
            if corners[0]!=hline_color and all(v==corners[0] for v in corners):
                line.append(corners[0])
            else:
                line.append(fill)
        out.append(line)
    # Remove unused grid area; remaining background cells are meaningful inside the crop.
    occupied=[(r,c) for r,row in enumerate(out) for c,v in enumerate(row) if v!=fill]
    if not occupied: return [[fill]]
    r0=min(r for r,c in occupied); r1=max(r for r,c in occupied)
    c0=min(c for r,c in occupied); c1=max(c for r,c in occupied)
    return [row[c0:c1+1] for row in out[r0:r1+1]]
