source='''import collections
import statistics


def _regular_group(labels):
    groups = collections.defaultdict(list)
    for index, value in enumerate(labels):
        groups[value].append(index)
    candidates = []
    for value, positions in groups.items():
        if len(positions) >= 2:
            gaps = [b - a for a, b in zip(positions, positions[1:])]
            median_gap = statistics.median(gaps)
            if median_gap > 1:
                candidates.append((median_gap, len(positions), value, positions))
    if not candidates:
        return None
    return max(candidates, key=lambda item: (item[0], item[1]))


def transform(grid):
    height, width = len(grid), len(grid[0])
    row_dominants = [collections.Counter(row).most_common(1)[0][0] for row in grid]
    row_group = _regular_group(row_dominants)
    if row_group is None:
        raise ValueError("Could not identify horizontal grid lines")
    line_color, rows = row_group[2], row_group[3]

    column_dominants = [
        collections.Counter(grid[r][c] for r in range(height)).most_common(1)[0][0]
        for c in range(width)
    ]
    column_group = _regular_group(column_dominants)
    if column_group is not None:
        columns = column_group[3]
    else:
        columns = [
            c for c in range(width)
            if sum(grid[r][c] != line_color for r in rows) >= 2
        ]
    if len(rows) < 2 or len(columns) < 2:
        raise ValueError("Could not identify grid intersections")

    fill = collections.Counter(value for row in grid for value in row).most_common(1)[0][0]
    output = []
    for ri in range(len(rows) - 1):
        output_row = []
        for ci in range(len(columns) - 1):
            corners = (
                grid[rows[ri]][columns[ci]],
                grid[rows[ri]][columns[ci + 1]],
                grid[rows[ri + 1]][columns[ci]],
                grid[rows[ri + 1]][columns[ci + 1]],
            )
            if corners[0] != line_color and all(value == corners[0] for value in corners):
                output_row.append(corners[0])
            else:
                output_row.append(fill)
        output.append(output_row)

    marked = [(r, c) for r, row in enumerate(output) for c, value in enumerate(row) if value != fill]
    if not marked:
        return [[fill]]
    r0 = min(r for r, _ in marked)
    r1 = max(r for r, _ in marked)
    c0 = min(c for _, c in marked)
    c1 = max(c for _, c in marked)
    return [row[c0:c1 + 1] for row in output[r0:r1 + 1]]
